<?php
declare(strict_types=1);
namespace Dreamsmith\Campaign\LeadFinder;
use Dreamsmith\Campaign\Authentication\AuthenticationService;use Dreamsmith\Campaign\Http\Request;use Dreamsmith\Campaign\Http\Response;use Dreamsmith\Campaign\Http\Router;use Dreamsmith\Campaign\Persistence\Database;use Dreamsmith\Campaign\Presentation\FlashBag;use Dreamsmith\Campaign\Presentation\ShellRenderer;use Dreamsmith\Campaign\Security\Csrf;use Dreamsmith\Campaign\Records\RecordService;use Dreamsmith\Campaign\Records\CompanyInput;use Dreamsmith\Campaign\Records\DuplicateWarning;use Dreamsmith\Campaign\Prospect\ProspectService;use Dreamsmith\Campaign\Prospect\ProspectInput;
final class LeadFinderController {
 public function __construct(private readonly AuthenticationService $auth,private readonly Database $db,private readonly RecordService $records,private readonly ProspectService $prospects,private readonly array $sales,private readonly ShellRenderer $shell,private readonly FlashBag $flash,private readonly Csrf $csrf,private readonly Router $router){}
 public function index(Request $request):Response{$user=$this->user();if($user instanceof Response)return $user;$status=in_array($request->query['status']??'', ['pending','approved','rejected'],true)?$request->query['status']:'pending';$rows=(new LeadCandidateRepository($this->db->pdo()))->all($status);foreach($rows as &$row)$row['evidence']=json_decode((string)$row['evidence_json'],true)?:[];unset($row);return $this->shell->owner('lead-finder/index.php',['candidates'=>$rows,'status'=>$status,'segments'=>$this->sales['segments'],'csrfToken'=>$this->csrf->token(),'indexUrl'=>$this->router->url('lead-finder.index'),'reviewUrl'=>fn(int $id)=>$this->router->url('lead-finder.review',['id'=>$id])],$user,'Lead Finder','lead-finder.index');}
 public function profile():Response{$user=$this->user();if($user instanceof Response)return $user;$profile=(new LeadProfileRepository($this->db->pdo()))->current();return $this->shell->owner('lead-finder/profile.php',['profile'=>$profile,'csrfToken'=>$this->csrf->token(),'actionUrl'=>$this->router->url('lead-finder.profile.update'),'uploadUrl'=>$this->router->url('lead-finder.profile.upload'),'indexUrl'=>$this->router->url('lead-finder.index')],$user,'Ideal customer profile','lead-finder.profile');}
 public function updateProfile(Request $request):Response{$user=$this->user();if($user instanceof Response)return $user;if(!$this->csrf->verify($request->body['_csrf']??null))return Response::html('Forbidden',403);try{$profile=['description'=>substr(trim((string)($request->body['description']??'')),0,500),'required_any'=>$this->lines($request->body['required_any']??''),'positive_keywords'=>$this->weights($request->body['positive_keywords']??''),'negative_keywords'=>$this->lines($request->body['negative_keywords']??''),'preferred_locations'=>$this->lines($request->body['preferred_locations']??''),'minimum_score'=>max(1,min(100,(int)($request->body['minimum_score']??1))),'strong_fit_score'=>max(1,min(100,(int)($request->body['strong_fit_score']??3)))];if($profile['strong_fit_score']<$profile['minimum_score'])throw new \InvalidArgumentException('Strong-fit score must be at least the minimum score.');if(!(new LeadProfileRepository($this->db->pdo()))->update($profile,(int)($request->body['version']??0),(int)$user['id']))throw new \RuntimeException('The profile changed. Reload it before saving.');$this->flash->add('success','Ideal customer profile saved. New lead searches will use it.');}catch(\Throwable $e){$this->flash->add('error',$e->getMessage());}return Response::redirect($this->router->url('lead-finder.profile'));}
 public function uploadProfileField(Request $request):Response{$user=$this->user();if($user instanceof Response)return Response::json(['error'=>'Sign in is required.'],401);if(!$this->csrf->verify($request->body['_csrf']??null))return Response::json(['error'=>'Your session has expired. Reload this page and try again.'],403);$field=(string)($request->body['field']??'');if(!in_array($field,['description','required_any','positive_keywords','negative_keywords','preferred_locations'],true))return Response::json(['error'=>'Choose a valid profile field.'],422);try{$text=(new ProfileFieldUpload())->text(is_array($request->files['profile_file']??null)?$request->files['profile_file']:null);if($text===null)throw new \InvalidArgumentException('Choose a file first.');return Response::json(['text'=>$text]);}catch(\InvalidArgumentException $e){return Response::json(['error'=>$e->getMessage()],422);}}
 public function review(Request $request,int $id):Response{$user=$this->user();if($user instanceof Response)return $user;if(!$this->csrf->verify($request->body['_csrf']??null))return Response::html('Forbidden',403);$status=(string)($request->body['status']??'');if(!in_array($status,['approved','rejected'],true))return Response::html('Invalid review action.',422);$repository=new LeadCandidateRepository($this->db->pdo());$candidate=$repository->find($id);if($candidate===null||$candidate['status']!=='pending'){$this->flash->add('warning','That lead was already reviewed.');return Response::redirect($this->router->url('lead-finder.index'));}if($status==='rejected'){$repository->review($id,'rejected',(int)$user['id']);$this->flash->add('success','Lead rejected.');return Response::redirect($this->router->url('lead-finder.index'));}[$company,$companyErrors]=CompanyInput::fromArray(['name'=>$candidate['name'],'website'=>$candidate['website'],'location'=>$candidate['address'],'industry'=>$candidate['category'],'notes'=>implode("\n",json_decode((string)$candidate['evidence_json'],true)?:[])]);[$prospect,$prospectErrors]=ProspectInput::fromArray(['company_id'=>'1','segment'=>$request->body['segment']??'','source'=>'Lead Finder: '.$candidate['source'],'why_them'=>implode("\n",json_decode((string)$candidate['evidence_json'],true)?:[])],$this->sales);if($company===null||$prospect===null){$this->flash->add('error',reset($companyErrors)?:reset($prospectErrors)?:'Could not create this prospect.');return Response::redirect($this->router->url('lead-finder.index'));}try{$companyId=$this->records->createCompany($company,false,(int)$user['id'],$request->requestId);$prospectInput=new ProspectInput($companyId,null,$prospect->segment,$prospect->source,$prospect->whyThem,$prospect->businessProblem,$prospect->qualificationNotes,false,false,false,false);$prospectId=$this->prospects->create($prospectInput,(int)$user['id'],$request->requestId);$repository->review($id,'approved',(int)$user['id']);$this->flash->add('success','Lead approved and prospect created.');return Response::redirect($this->router->url('prospects.show',['id'=>$prospectId]));}catch(DuplicateWarning $e){$this->flash->add('error','A matching company already exists. Open Companies to use the existing record instead.');}catch(\DomainException $e){$this->flash->add('error',$e->getMessage());}return Response::redirect($this->router->url('lead-finder.index'));}
 private function user():array|Response{return $this->auth->user()??Response::redirect($this->router->url('login.form').'?return=lead-finder',302);}
 /** @return list<string> */ private function lines(mixed $value):array{$lines=preg_split('/\R/',is_string($value)?$value:'')?:[];$lines=array_values(array_unique(array_filter(array_map(static fn(string $line):string=>substr(trim($line),0,160),$lines),static fn(string $line):bool=>$line!=='')));if(count($lines)>50)throw new \InvalidArgumentException('Use no more than 50 entries.');return $lines;}
 /** @return array<string,int> */ private function weights(mixed $value):array{$out=[];foreach(preg_split('/\R/',is_string($value)?$value:'')?:[] as $line){[$term,$weight]=array_pad(explode('|',$line,2),2,'');$term=substr(trim($term),0,160);if($term==='')continue;$out[$term]=max(1,min(20,(int)trim($weight?:'1')));}if(count($out)>50)throw new \InvalidArgumentException('Use no more than 50 positive signals.');return $out;}
}
